// 项目内可分派、可执行的工作项
type ProjectTask struct {
	// 项目任务ID
	ID uuid.UUID `json:"id"`
	// 租户ID
	TenantID uuid.UUID `json:"tenant_id"`
	// 所属项目ID
	ProjectID uuid.UUID `json:"project_id"`
	// 关联项目需求ID
	DemandID uuid.NullUUID `json:"demand_id"`
	// 项目任务标题
	Title string `json:"title"`
	// 项目任务摘要
	Summary pgtype.Text `json:"summary"`
	// 任务状态：pending, planned, queued, assigned, blocked, running, waiting_human, completed, failed, cancelled；queued 表示已分派并等待 Runtime 真正启动。
	Status string `json:"status"`
	// 当前分派的数字员工ID
	AssignedDigitalEmployeeID uuid.NullUUID `json:"assigned_digital_employee_id"`
	// 关联的底层 Runtime 任务ID（若有）
	RuntimeTaskID uuid.NullUUID `json:"runtime_task_id"`
	// 关联的数字员工执行记录ID（若有）
	DigitalEmployeeRunID uuid.NullUUID `json:"digital_employee_run_id"`
	// 任务风险等级，由应用层和策略校验
	RiskLevel pgtype.Text `json:"risk_level"`
	// 是否需要人类审批后继续
	RequiresHumanApproval bool `json:"requires_human_approval"`
	// 最新关联项目事件ID
	LatestEventID uuid.NullUUID `json:"latest_event_id"`
	// 项目任务创建时间
	CreatedAt pgtype.Timestamptz `json:"created_at"`
	// 项目任务更新时间
	UpdatedAt pgtype.Timestamptz `json:"updated_at"`
	// 创建该任务的项目协调作业ID，由应用层校验租户和项目范围
	CoordinationJobID uuid.NullUUID `json:"coordination_job_id"`
	// 创建该任务的路由决策ID，由应用层校验租户和项目范围
	RouteDecisionID uuid.NullUUID `json:"route_decision_id"`
	// Planner在同一协调图内生成的稳定任务键，用于幂等重放和图展示
	PlannedTaskKey pgtype.Text `json:"planned_task_key"`
	// 任务类型开放字符串，例如 analysis、implementation、review、test 或 summary，由应用层注册校验
	TaskKind pgtype.Text `json:"task_kind"`
	// 任务在规划图中的展示阶段序号，执行事实仍以依赖边为准
	StageIndex pgtype.Int4 `json:"stage_index"`
	// 任务级输出契约数组，用于完成前校验和下游交接
	ExpectedOutputs []byte `json:"expected_outputs"`
	// 任务输入要求JSON，描述执行该任务需要的上下文切片
	InputRequirements []byte `json:"input_requirements"`
	// 任务交接契约JSON，描述下游可消费的证据、工件、结论和引用要求
	HandoffContract []byte `json:"handoff_contract"`
	// Planner审计摘要JSON，不保存长prompt或模型原文
	PlannerMetadata []byte `json:"planner_metadata"`
	// 当前项目任务执行尝试ID，指向当前 queued、running 或 waiting_human 尝试。
	CurrentAttemptID uuid.NullUUID `json:"current_attempt_id"`
	// 生成该任务的已接受计划版本ID。
	AcceptedPlanRevisionID uuid.NullUUID `json:"accepted_plan_revision_id"`
	// 计划分解幂等声明键，用于同一计划分解重复写入去重。
	DecompositionClaimKey pgtype.Text `json:"decomposition_claim_key"`
	// 任务执行尝试次数。
	AttemptCount int32 `json:"attempt_count"`
	// 任务允许的最大执行尝试次数。
	MaxAttempts pgtype.Int4 `json:"max_attempts"`
	// 任务下次可重试时间。
	RetryNotBefore pgtype.Timestamptz `json:"retry_not_before"`
	// 任务等待人类或外部条件的原因。
	WaitingReason pgtype.Text `json:"waiting_reason"`
	// 任务等待的人类决策或请求ID。
	WaitingRequestID uuid.NullUUID `json:"waiting_request_id"`
	// 任务进入终态时写入的项目事件ID。
	TerminalEventID uuid.NullUUID `json:"terminal_event_id"`
	// 任务状态最近一次变化时间。
	StatusChangedAt pgtype.Timestamptz `json:"status_changed_at"`
	// 该任务最近一次 gate 结果ID。
	LatestDispatchGateResultID uuid.NullUUID `json:"latest_dispatch_gate_result_id"`
	// 该任务是否为另一个 ProjectTask 的 append-only 修订任务。
	RevisionOfTaskID uuid.NullUUID `json:"revision_of_task_id"`
	// 该任务最新结构化结果记录ID。
	LatestTaskResultID uuid.NullUUID `json:"latest_task_result_id"`
	// Graph extension round: 0 for the original plan, N for tasks appended in the Nth round.
	PlanIteration int32 `json:"plan_iteration"`
	// 人类了结该终态任务的时间;有值后任务从活跃视图/项目风险/员工运营态中隐藏,status 与审计不变
	DismissedAt pgtype.Timestamptz `json:"dismissed_at"`
	// 了结该任务的用户 ID
	DismissedBy uuid.NullUUID `json:"dismissed_by"`
}

// 项目任务执行尝试表，记录项目任务调度、租约、重试和终态回写。
type ProjectTaskAttempt struct {
	// 执行尝试主键ID。
	ID uuid.UUID `json:"id"`
	// 执行尝试所属租户ID。
	TenantID uuid.UUID `json:"tenant_id"`
	// 执行尝试所属项目任务ID。
	ProjectTaskID uuid.UUID `json:"project_task_id"`
	// 尝试序号，从 1 开始递增。
	AttemptNo int32 `json:"attempt_no"`
	// 尝试状态：queued, running, succeeded, failed, cancelled, lost, timed_out, waiting_human。
	Status string `json:"status"`
	// 执行尝试关联的数字员工运行ID。
	DigitalEmployeeRunID uuid.NullUUID `json:"digital_employee_run_id"`
	// 执行尝试关联的 Runtime 任务ID。
	RuntimeTaskID uuid.NullUUID `json:"runtime_task_id"`
	// 执行尝试所在 Runtime 节点ID。
	RuntimeNodeID uuid.NullUUID `json:"runtime_node_id"`
	// 执行尝试关联的 Provider 会话ID。
	ProviderSessionID pgtype.Text `json:"provider_session_id"`
	// 执行上下文包 JSON，保存下发给 Runtime 的任务上下文切片。
	ExecutionContextPacket []byte `json:"execution_context_packet"`
	// 执行上下文包版本。
	ExecutionContextPacketVersion string `json:"execution_context_packet_version"`
	// Runtime 租约令牌。
	LeaseToken string `json:"lease_token"`
	// Runtime 租约过期时间。
	LeaseExpiresAt pgtype.Timestamptz `json:"lease_expires_at"`
	// Runtime 租约最近续约时间。
	RenewedAt pgtype.Timestamptz `json:"renewed_at"`
	// 执行尝试开始时间。
	StartedAt pgtype.Timestamptz `json:"started_at"`
	// 执行尝试结束时间。
	FinishedAt pgtype.Timestamptz `json:"finished_at"`
	// 执行失败后是否允许重试。
	Retryable pgtype.Bool `json:"retryable"`
	// 执行失败分类。
	FailureFamily pgtype.Text `json:"failure_family"`
	// 执行失败说明。
	FailureMessage pgtype.Text `json:"failure_message"`
	// 执行尝试创建幂等键。
	IdempotencyKey string `json:"idempotency_key"`
	// 执行尝试创建时写入的项目事件ID。
	CreatedEventID uuid.NullUUID `json:"created_event_id"`
	// 执行尝试进入终态时写入的项目事件ID。
	TerminalEventID uuid.NullUUID `json:"terminal_event_id"`
	// 执行尝试创建时间。
	CreatedAt pgtype.Timestamptz `json:"created_at"`
	// 执行尝试最近更新时间。
	UpdatedAt pgtype.Timestamptz `json:"updated_at"`
	// 创建该尝试前通过的 gate 结果ID。
	DispatchGateResultID uuid.NullUUID `json:"dispatch_gate_result_id"`
	// 该尝试的墙钟预算上限，空表示未设置。
	BudgetWallClockLimitSec    pgtype.Int4        `json:"budget_wall_clock_limit_sec"`
	BudgetLastHeartbeatAt      pgtype.Timestamptz `json:"budget_last_heartbeat_at"`
	BudgetConsumedWallClockSec int32              `json:"budget_consumed_wall_clock_sec"`
	BudgetConsumedTokens       int32              `json:"budget_consumed_tokens"`
	BudgetTrippedAt            pgtype.Timestamptz `json:"budget_tripped_at"`
	// 预算熔断原因，例如 wall_clock_exceeded、token_limit_exceeded。
	BudgetTripReason pgtype.Text `json:"budget_trip_reason"`
	// 执行尝试实际分派的数字员工 ID，历史记录可为空。
	DigitalEmployeeID uuid.NullUUID `json:"digital_employee_id"`
	// 执行尝试使用的 Provider 类型，优先来自上下文包或数字员工主 Provider。
	ProviderType pgtype.Text `json:"provider_type"`
	// Raw transcript backend: object_store | local_file
	LogStore pgtype.Text `json:"log_store"`
	// Opaque reference to the raw transcript manifest
	LogRef pgtype.Text `json:"log_ref"`
	// Total raw transcript bytes across all segments
	LogBytes pgtype.Int8 `json:"log_bytes"`
	// Runtime-reported sha256 of the concatenated raw transcript; must be recomputed before being trusted
	LogSha256 pgtype.Text `json:"log_sha256"`
	// Whether raw transcript segments are stored compressed
	LogCompressed bool `json:"log_compressed"`
}

